<?php $activityIcons = ['CALL' => 'telephone', 'MEETING' => 'camera-video', 'WHATSAPP' => 'whatsapp', 'EMAIL' => 'envelope', 'FOLLOW_UP' => 'calendar2-check', 'NOTE' => 'journal-text', 'OTHER' => 'three-dots']; ?>
<div class="page-heading"><div><span class="eyebrow">DAILY EXECUTION</span><h1>Activities</h1><p>Every customer interaction in one simple timeline.</p></div></div>
<section class="panel">
    <div class="activity-tabs"><a class="<?= ($_GET['tab'] ?? 'today') === 'today' ? 'active' : '' ?>" href="<?= e(url('activities?tab=today')) ?>">Today</a><a class="<?= ($_GET['tab'] ?? 'today') === 'history' ? 'active' : '' ?>" href="<?= e(url('activities?tab=history')) ?>">History</a><form method="get"><input type="hidden" name="tab" value="<?= e((string) ($_GET['tab'] ?? 'today')) ?>"><select class="form-select form-select-sm" name="activity_type" onchange="this.form.submit()"><option value="">All activity types</option><?php foreach ($activityTypes as $type): ?><option value="<?= e($type) ?>" <?= ($_GET['activity_type'] ?? '') === $type ? 'selected' : '' ?>><?= e(ucwords(strtolower(str_replace('_', ' ', $type)))) ?></option><?php endforeach; ?></select></form></div>
    <div class="table-responsive"><table class="table align-middle"><thead><tr><th>Activity</th><th>Lead</th><th>Outcome</th><th>Created by</th><th>Date & time</th></tr></thead><tbody><?php foreach ($activities as $activity): ?><tr><td><span class="activity-type"><i class="bi bi-<?= e($activityIcons[$activity['activity_type']] ?? 'activity') ?>"></i><?= e(ucwords(strtolower(str_replace('_', ' ', $activity['activity_type'])))) ?></span></td><td><a class="lead-name" href="<?= e(url('leads/'.$activity['lead_id'])) ?>"><?= e($activity['lead_name']) ?></a></td><td><?= e($activity['outcome'] ?: $activity['notes'] ?: '—') ?></td><td><?= e($activity['user_name']) ?></td><td><?= e(date('d M Y, g:i A', strtotime($activity['activity_datetime']))) ?></td></tr><?php endforeach; ?><?php if (! $activities): ?><tr><td colspan="5"><div class="empty-state"><i class="bi bi-calendar-check"></i><p>No activities found for this view.</p></div></td></tr><?php endif; ?></tbody></table></div>
</section>
